function merchantPage() {ensureMerchant(state);const titles={overview:['Кабинет поставщика','Принимайте карты вашей компании по договорам и заказам'],registry:['Реестр активаций','Покупатели, договоры и суммы принятых карт'],settlements:['Баланс и расчёты','Банковские переводы и учётный остаток — отдельно'],company:['Реквизиты и договор','Заполните данные и подготовьте рамочный договор']};const [title,subtitle]=titles[merchantTab];return `<div class="shell merchant-shell"><aside class="sidebar"><a class="logo" href="#/" aria-label="Pina Market — главная">${logo()}</a><span class="merchant-role-label">КАБИНЕТ ПОСТАВЩИКА</span><nav class="nav" aria-label="Кабинет поставщика">${[['overview','redemption','Приём карты'],['registry','orders','Реестр активаций'],['settlements','reports','Баланс и расчёты'],['company','contract','Реквизиты и договор']].map(([id,i,n])=>`<a href="#/merchant/${id}" class="${id===merchantTab?'active':''}" ${id===merchantTab?'aria-current="page"':''}>${icon(i)}<span>${n}</span></a>`).join('')}</nav><div class="side-bottom"><div class="side-box">Нужна помощь?<a href="mailto:mail@pina.market">mail@pina.market ${icon('arrow')}</a></div><a class="back-link" href="#/account">Кабинет покупателя ${icon('arrow')}</a><a class="back-link" href="#/">На главную ${icon('arrow')}</a></div></aside><main class="main" id="main"><header class="topbar"><span class="crumb">Для бизнеса <span>/</span> ${title}</span><a class="mobile-logo" href="#/">${logo()}</a><span class="profile"><span>Поставщик<small>Демонстрационный аккаунт</small></span><b class="avatar">П</b></span></header><div class="page-head"><div><p class="eyebrow">Подарочные карты вашей компании</p><h1>${title}</h1><p>${subtitle}</p></div><a class="btn outline small" href="#/account">Покупатель ${icon('arrow')}</a></div>${merchantContent(state,merchantTab,{icon,btn})}<div class="account-bottom">${icon('shield-check')}Демо · Банк и V-DAR не подключены</div></main></div>`;}
async function contractDownload() {const m=ensureMerchant(state);if(!m.contract)throw Error('Сначала заполните реквизиты.');toast('Готовим заполненный проект договора…');const blob=await generateContract(m.company,m.contract);downloadBlob(blob,m.contract.number+'.docx');toast('Проект договора скачан. Подпись Pina Market пока не добавлена.');}
function settlementDialog() {const rows=merchantTotals(state).awaiting.filter(x=>x.card.refund==='none'),ids=rows.map(x=>x.card.id),nominal=rows.reduce((a,x)=>a+x.card.nominal,0);if(!ids.length)throw Error('Нет готовых к подтверждению переводов.');openModal(`<p class="eyebrow">Подтверждение поставщика · демо</p><h2>Перевод получен?</h2><p class="intro">Номинал реестра: ${money(nominal)}. Демо-удержания: 0,1% вознаграждение и 0,8% расходы финансовой организации. К получению: <b>${money(nominal*991/1000)}</b>.</p><form id="settlement-form" data-cards="${ids.join(',')}" class="fields"><div class="field"><label for="received-amount">Фактически получено, ₽</label><input id="received-amount" name="amount" required type="number" min="0.01" step="0.01" value="${(nominal*991/1000).toFixed(2)}"></div><div class="field"><label for="received-ref">Номер банковского подтверждения</label><input id="received-ref" name="bankref" required maxlength="150" placeholder="ДЕМО-выписка-001"></div><label class="checkline"><input type="checkbox" required><span>Сверил банковское поступление и реестр. Подтверждаю получение суммы в демонстрации.</span></label><div class="notice">После подтверждения оператор отдельно сверит учётный остаток платформы. Автоматический перевод остатка не выполняется.</div><p class="form-error" role="alert" hidden></p><button class="btn full">Подтвердить получение в демо</button></form>`,'Подтверждение расчёта');}
