   if(f.id==='company-form'){for(const [key] of COMPANY_FIELDS)if(!d[key]?.trim())throw Error('Заполните все обязательные реквизиты и условия программы.');const m=ensureMerchant(state);m.company=Object.fromEntries(COMPANY_FIELDS.map(([key])=>[key,d[key].trim()]));m.contract??={number:'PM-DEMO-'+new Date().getFullYear()+'-'+crypto.randomUUID().slice(0,8).toUpperCase(),date:new Date().toISOString()};m.uploaded=null;save();render();await contractDownload();}
